//! Fixed affine sequence views and source-funded Unicode text slicing.
use super::*;
use primitive::slice::Plan;
use generated::Output;
use measured::Measured;
use std::fmt::Write;

#[derive(Clone, Copy, Debug)]
pub(super) enum Base {
    Empty,
    Sequence(values::Value),
    ObjectView(object::View),
    Messages,
    Range(range::Value),
    Split(SplitView),
    Mapping(MappingView),
    Pair(MappingPair),
    Structured { register: usize, length: usize },
}
impl Base {
    pub(super) fn slot(self) -> Slot {
        match self {
            Self::ObjectView(value)=>Slot::ObjectView(value),
            Self::Sequence(value)=>Slot::Sequence(value),
            Self::Empty=>Slot::EmptySequence, Self::Messages=>Slot::Messages,
            Self::Range(value)=>Slot::Range(value), Self::Split(value)=>Slot::Split(value),
            Self::Mapping(value)=>Slot::Mapping(value), Self::Pair(value)=>Slot::MappingPair(value),
            Self::Structured{register,length}=>Slot::Structured{register,length},
        }
    }
    pub(super) fn from_slot(value: Slot) -> Result<Self, Error> {
        Ok(match value {
            Slot::ObjectView(value)=>Self::ObjectView(value),
            Slot::Sequence(value)=>Self::Sequence(value),
            Slot::EmptySequence=>Self::Empty, Slot::Messages=>Self::Messages,
            Slot::Range(value)=>Self::Range(value), Slot::Split(value)=>Self::Split(value),
            Slot::Mapping(value)=>Self::Mapping(value), Slot::MappingPair(value)=>Self::Pair(value),
            Slot::Structured{register,length}=>Self::Structured{register,length},
            _=>return Err(Error::Geometry),
        })
    }
}
#[derive(Clone, Copy, Debug)]
pub(super) struct View {
    pub base: Base,
    pub plan: Plan,
    pub listed: bool,
}
fn bound(value: Slot) -> Result<Option<i64>, Error> {
    match scalar(value) {
        Some(Scalar::None)=>Ok(None),
        Some(value)=>primitive::scalar::signed(value).and_then(|v|i64::try_from(v).ok()).map(Some).ok_or(Error::Geometry),
        None=>Err(Error::Geometry),
    }
}
impl Engine<'_, '_, '_> {
    pub(super) fn slice_value(&mut self, value: Slot, start: Slot, stop: Slot, step: Slot) -> Result<Slot, Error> {
        let start=bound(start)?; let stop=bound(stop)?; let step=bound(step)?.unwrap_or(1);
        if step==0 {return Err(Error::Geometry);}
        if matches!(value,Slot::Undefined|Slot::Scalar(Scalar::None)) {return Ok(Slot::EmptySequence);}
        let length=self.value_length(value)?;
        let plan=Plan::new(length,start,stop,step).ok_or(Error::Overflow)?;
        if let Slot::Text(text)=value {return self.slice_text(text,plan);}
        if let Slot::Slice(view)=value {
            return Ok(Slot::Slice(View {base:view.base,plan:view.plan.compose(plan).ok_or(Error::Overflow)?,listed:false}));
        }
        #[cfg(feature="json")]
        if let Slot::Structured{register,..}=value {
            if !self.borrowed.get(register)?.is_array() {return Err(Error::Geometry);}
        }
        Ok(Slot::Slice(View {base:Base::from_slot(value)?,plan,listed:false}))
    }
    pub(super) fn slice_item(&mut self, view:View, key:Slot)->Result<Slot,Error>{
        let Some(index)=structured::index(key,view.plan.length).and_then(|i|view.plan.index(i)) else{return Ok(Slot::Undefined);};
        self.selected_item(view.base.slot(),Slot::Scalar(Scalar::U64(u64::try_from(index).map_err(|_|Error::Overflow)?)))
    }
    fn slice_text(&mut self,text:Text,plan:Plan)->Result<Slot,Error>{
        // A later consumer must inspect actual generated bytes. Request the
        // reached prefix, retire this attempt, and admit the next fixed buffer.
        let needed=super::super::render::TextCapacity{atoms:self.counts.concat,bytes:self.counts.context_text};
        let atom_capacity=self.workspace.concat.as_ref().map_or(0,|v|v.len());
        let byte_capacity=self.workspace.context_text.as_ref().map_or(0,|v|v.len());
        if atom_capacity<needed.atoms || byte_capacity<needed.bytes {return Err(Error::TextCapacity(needed));}
        let (start,text_start)=self.generated_start()?;
        let (prefix,destination)=match self.workspace.context_text.as_deref_mut(){
            Some(bytes)=>{let (prefix,tail)=bytes.split_at_mut(text_start);(Some(&*prefix),Some(tail))},
            None=>(None,None),
        };
        let mut output=Output{bytes:destination,start:0,measured:Measured::default(),error:None};
        write_text(text,self.source,self.context,self.borrowed,prefix,self.workspace.concat.as_deref(),plan,&mut output)?;
        let measured=output.finish().map_err(|cause|match cause{
            Error::TextCapacity(next)=>Error::TextCapacity(super::super::render::TextCapacity {
                atoms:needed.atoms,bytes:text_start.checked_add(next.bytes).unwrap_or(usize::MAX)
            }),
            other=>other,
        })?;
        self.finish_generated(start,text_start,measured)?;
        self.pop()
    }
}
fn write_text(
    text:Text,source:&PreparedTemplate,context:RenderContext<'_>,borrowed:&Borrowed<'_>,
    prefix:Option<&[u8]>,atoms:Option<&[Atom]>,plan:Plan,output:&mut Output<'_>,
)->Result<(),Error>{
    let (first,count,mut skip,mut remaining)=match text {
        Text::Atom(atom)=>(0,1,0,atom_text(source,context,borrowed,prefix,atom)?.len()),
        Text::Concat{start,count,skip,bytes,..}=>(start,count,skip,bytes),
    };
    let atom_at=|index:usize|->Result<Atom,Error>{
        match text {Text::Atom(atom)=>Ok(atom),_=>atoms.and_then(|v|v.get(first+index)).copied().ok_or(Error::Geometry)}
    };
    let reverse=plan.stride<0;
    if reverse {
        let mut total=0usize;
        for index in 0..count {total=total.checked_add(atom_text(source,context,borrowed,prefix,atom_at(index)?)?.len()).ok_or(Error::Overflow)?;}
        skip=total.checked_sub(skip).and_then(|n|n.checked_sub(remaining)).ok_or(Error::Geometry)?;
    }
    let mut selected=0usize;
    let mut position=if reverse {match text {
        Text::Concat{characters,..}=>characters,
        Text::Atom(atom)=>atom_text(source,context,borrowed,prefix,atom)?.chars().count(),
    }}else{0};
    for ordinal in 0..count {
        let index=if reverse{count-1-ordinal}else{ordinal};
        let part=atom_text(source,context,borrowed,prefix,atom_at(index)?)?;
        let ignored=skip.min(part.len());skip-=ignored;
        let take=(part.len()-ignored).min(remaining);remaining-=take;
        let part=if reverse{part.get(part.len()-ignored-take..part.len()-ignored)}else{part.get(ignored..ignored+take)}.ok_or(Error::Geometry)?;
        let mut chars=part.chars();
        loop {
            let character=if reverse{chars.next_back()}else{chars.next()};
            let Some(character)=character else{break;};
            if reverse {position=position.checked_sub(1).ok_or(Error::Geometry)?;}
            if plan.index(selected)==Some(position) {
                output.write_char(character).map_err(|_|output.error.unwrap_or(Error::Geometry))?;
                selected=selected.checked_add(1).ok_or(Error::Overflow)?;
            }
            if !reverse {position=position.checked_add(1).ok_or(Error::Overflow)?;}
        }
    }
    if skip!=0 || remaining!=0 || selected!=plan.length {return Err(Error::Geometry);}
    Ok(())
}
pub(super) fn control_bytes()->Option<usize>{
    use std::mem::{size_of,size_of_val};
    let frames=[
        size_of::<Base>(),size_of::<View>(),size_of::<Plan>(),
        size_of::<[Slot;4]>(),size_of::<[Option<i64>;3]>(),size_of::<[usize;14]>(),
        size_of::<[Text;2]>(),size_of::<Output<'_>>(),size_of::<Measured>(),
        size_of::<(&PreparedTemplate,RenderContext<'_>,&Borrowed<'_>,Option<&[u8]>,Option<&[Atom]>,Plan,&mut Output<'_>)>(),
        size_of::<(Option<&[u8]>,Option<&mut[u8]>)>(),size_of::<std::str::Chars<'_>>(),
        size_of::<[u8;4]>(),size_of::<Result<Slot,Error>>(),size_of::<Result<(),Error>>(),
        size_of::<Result<Measured,Error>>(),size_of::<super::super::render::TextCapacity>(),
        size_of::<(&Engine<'_, '_, '_>,Text,Plan)>(),
    ];
    frames.into_iter().try_fold(size_of_val(&frames),usize::checked_add)
}
